                for (int k0 = 0; k0 < n; k0 += kcb) {
                    int kc = n - k0 < kcb ? n - k0 : kcb;
                    int first = (k0 == 0);

                    for (int sb = s0; sb < s1; sb += MCS) {
                        int se = sb + MCS < s1 ? sb + MCS : s1;
                        for (int s = sb; s < se; s++)
                            pack_a_strip(A, n, s, k0, kc, Ap + (size_t)(s - sb) * MR * kc);

                        for (int p = p0; p < p1; p++) {
                            const float *bp = Bp + (size_t)p * n * NR + (size_t)k0 * NR;
                            int j = p * NR;
                            int nr = n - j < NR ? n - j : NR;
                            for (int s = sb; s < se; s++) {
                                const float *ap = Ap + (size_t)(s - sb) * MR * kc;
                                int i = s * MR;
                                int mr = n - i < MR ? n - i : MR;
                                float *cp = C + (size_t)i * n + j;
                                if (mr == MR && nr == NR) {
                                    kern(kc, ap, bp, cp, (size_t)n, first);
                                } else {
                                    float tmp[MR * NR] __attribute__((aligned(64)));
                                    kern(kc, ap, bp, tmp, NR, 1);
                                    for (int rr = 0; rr < mr; rr++) {
                                        float *cr = cp + (size_t)rr * n;
                                        const float *tr = tmp + rr * NR;
                                        if (first)
                                            for (int jj = 0; jj < nr; jj++) cr[jj] = tr[jj];
                                        else
                                            for (int jj = 0; jj < nr; jj++) cr[jj] += tr[jj];
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}
